  "initial_access": {
    "host": "host name",
    "vector": "controlled label",
    "execution": "controlled label",
    "assessment": "confirmed_compromise|suspected|benign",
    "evidence": [{"path": "relative/path", "locator": "unique record locator"}]
  },
  "lateral_movement": [
